 "content": "from collections import deque


def transform(grid):
    """Remove stray pixels and restore corrupted solid rectangular patches."""
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)
    seen = [[False] * w for _ in range(h)]
    patches = []

    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == background or seen[r][c]:
                continue
            q = deque([(r, c)])
            seen[r][c] = True
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy in (-1, 0, 1):
                    for dx in (-1, 0, 1):
                        if not (dy or dx):
                            continue
                        ny, nx = y + dy, x + dx
                        if (0 <= ny < h and 0 <= nx < w and not seen[ny][nx]
                                and grid[ny][nx] == color):
                            seen[ny][nx] = True
                            q.append((ny, nx))
            min_r = min(y for y, _ in cells)
            max_r = max(y for y, _ in cells)
            min_c = min(x for _, x in cells)
            max_c = max(x for _, x in cells)
            area = (max_r - min_r + 1) * (max_c - min_c + 1)
            # True objects are sizable, dense rectangular regions; isolated
            # speckles are distractors and are discarded.
            if area >= 6 and len(cells) >= 5 and len(cells) / area >= 0.40:
                patches.append((color, min_r, max_r, min_c, max_c))

    out = [[background] * w for _ in range(h)]
    for color, r0, r1, c0, c1 in patches:
        for r in range(r0, r1 + 1):
            for c in range(c0, c1 + 1):
                out[r][c] = color
    return out
